const parisGroups=[
 {name:'游荡者',fr:'Le flâneur',key:'street',position:'18% center',terms:['游荡者','漫游者'],text:'在人群中观察，在街道上居住。游荡者游离于消费与观看之间，也逐渐被商品世界吸纳。'},
 {name:'拾荒者',fr:'Le chiffonnier',key:'street',position:'55% center',terms:['拾荒者','拾垃圾','捡破烂'],text:'把城市抛弃的残片重新收集起来。这个劳动者的身影，也成为诗人与历史研究者的隐喻。'},
 {name:'收藏家',fr:'Le collectionneur',key:'commerce',position:'55% center',terms:['收藏家','收藏者','收藏'],text:'从流通中取回物，让物进入私人秩序；室内既是记忆的容器，也可能成为占有的幻景。'},
 {name:'店员',fr:'Les employés',key:'commerce',position:'15% center',terms:['店员','女店员','售货'],text:'橱窗之后的劳动者。商品的绚丽表面，依赖着销售、陈列与日常服务的劳动。'},
 {name:'赌徒',fr:'Le joueur',key:'commerce',position:'90% center',terms:['赌徒','赌博','博彩'],text:'每一次下注，都把希望与毁灭压缩到同一个瞬间。重复的偶然，构成现代生活的时间经验。'},
 {name:'性工作者',fr:'Les prostituées',key:'street',position:'85% center',terms:['妓女','卖淫'],text:'身体、劳动与交换在此交汇。阅读这些历史称谓，也需要看见其背后的生计与权力关系。'}
];
artwork.street={file:'assets/street.jpg',title:'暮色中的街头人群',credit:'AI 生成 · 群体主题插画，非历史实景'};
artwork.commerce={file:'assets/commerce.jpg',title:'长廊中的劳动与交易',credit:'AI 生成 · 群体主题插画，非历史实景'};
const groupHits=g=>{let a=[];chapters.forEach(c=>c.paragraphs.forEach((p,i)=>{if(g.terms.some(t=>p.includes(t)))a.push({c,p,i})}));return a};
function volumeCode(c){return c.title.match(/卷轴\s*([A-Za-z]+)/)?.[1]||'文稿'}
links=function(list){return list.map(c=>`<a class="chapter-link" href="#read/${c.id}"><span class="volume-code">${esc(volumeCode(c))}</span><span class="volume-title">${esc(c.title)}<small>${c.paragraphs.length} 段材料</small></span><span class="volume-enter">进入卷轴 ↗</span></a>`).join('')};
function memoryCards(){return entities.slice(0,5).map((e,i)=>`<a class="memory-card" href="#entity/${i}">${plate(entityArt[i])}<div class="memory-caption"><p>${e[1]}</p><h2>${e[0]}</h2><span>地点档案 ↗</span></div></a>`).join('')}
function groupCards(){return parisGroups.map((g,i)=>`<a class="group-card" href="#group/${i}"><div class="group-image"><img src="${artwork[g.key].file}" alt="${esc(g.name)}的主题插画" style="object-position:${g.position}" loading="lazy"></div><div><p>${g.fr}</p><h2>${g.name}</h2><p>${g.text}</p><span>阅读群体档案 ↗</span></div></a>`).join('')}
home=function(){return `<section class="night-hero"><div class="hero-image">${plate('dream','',true)}</div><div class="night-hero-copy"><p class="hero-book">瓦尔特·本雅明 · 拱廊街计划</p><h1>巴黎，<br>梦与废墟。</h1><p>玻璃之下的华丽，<br>人群背后的疲惫。</p><a class="primary-link" href="#library">进入卷轴书库 <span>↗</span></a></div><a href="#memory" class="hero-side-link">巴黎记忆 ↗</a></section><section class="section night-intro"><h2>精致与颓丧，<br>在同一条街上。</h2><div><blockquote>“拱廊街是一个城市，一个微缩的世界。”</blockquote><p class="note">文档摘引 · [A1,1]</p><div class="paths"><a href="#memory">巴黎记忆 ↗</a><a href="#characters">巴黎人物 ↗</a><a href="#random">随机片段 ↗</a></div></div></section><section class="section"><div class="section-heading"><h2>巴黎记忆</h2><a href="#memory">所有地点 ↗</a></div><div class="memory-grid">${memoryCards()}</div></section><section class="section"><div class="section-heading"><h2>巴黎人物</h2><a href="#characters">群体档案 ↗</a></div><div class="group-home">${groupCards()}</div></section><section class="section volume-teaser"><h2>卷轴书库</h2><p>从街道与事物，进入历史。</p>${links(chapters.slice(0,4))}<a href="#library" class="primary-link">全部 ${chapters.length} 个阅读单元 ↗</a></section>`};
library=function(term=''){return `<section class="section archive-library"><div class="library-backdrop">${plate('library')}</div><h1>卷轴书库</h1><label for="search">检索人物、地点或笔记编号</label><input id="search" type="search" placeholder="游荡者 / 波德莱尔 / A1,1" value="${esc(term)}"><div id="results" class="listing">${links(chapters)}</div></section>`};
reader=function(id,pos){let c=chapters.find(x=>x.id===id);if(!c)return library();return `<div class="reading"><aside><a href="#library" class="back-link">← 卷轴书库</a>${chapters.map(x=>`<a href="#read/${x.id}" ${x.id===id?'aria-current="page"':''}>${esc(x.title)}</a>`).join('')}</aside><article><div class="reading-scene">${plate(chapterArt(c),'chapter-painting',true)}<div class="reading-title"><p>${esc(volumeCode(c))}</p><h1>${esc(c.title)}</h1></div></div><div class="reading-body"><div class="tools"><button id="mark">${localStorage.getItem('read-'+id)?'已读':'标记为已读'}</button><a href="#notebook">阅读札记 ↗</a></div><p class="note">导览摘录与解读 · 引文版本待校对</p>${c.paragraphs.map((p,i)=>`<p id="p${i}" class="${/^\[[A-Za-z]|英文原文/.test(p)?'fragment':''}">${esc(p)}</p>`).join('')}<div class="tools">${+id>0?`<a class="primary-link" href="#read/${+id-1}">上一卷轴</a>`:''}${+id<chapters.length-1?`<a class="primary-link" href="#read/${+id+1}">下一卷轴 ↗</a>`:''}</div></div></article></div>`};
function memoryPage(){return `<section class="section topic-page"><div class="topic-heading"><div><p>Les lieux de Paris</p><h1>巴黎记忆</h1></div><p>长廊、商店与消失的空间。<br>从一个地点，打开一组历史碎片。</p></div><div class="memory-grid">${memoryCards()}</div></section>`}
function charactersPage(){return `<section class="section topic-page"><div class="topic-heading"><div><p>Les figures de Paris</p><h1>巴黎人物</h1></div><p>街头的观看者、劳动者与交易者。<br>阅读城市中的群体身影。</p></div><div class="group-grid">${groupCards()}</div><a class="primary-link" href="#figures">具名人物索引 ↗</a></section>`}
function groupPage(i){let g=parisGroups[i];if(!g)return charactersPage();let a=groupHits(g);return `<section class="section group-detail"><a href="#characters" class="back-link">← 巴黎人物</a><div class="group-detail-hero"><img src="${artwork[g.key].file}" alt="${esc(g.name)}群体主题插画" style="object-position:${g.position}"><div><p>${g.fr}</p><h1>${g.name}</h1><p>${g.text}</p><small>策展概述 · 图像为群体主题艺术演绎</small></div></div><h2>文档中的片段</h2><p class="note">${a.length} 段相关材料 · 下列摘录保留上下文入口</p>${a.slice(0,30).map(h=>`<blockquote class="group-excerpt"><p>${esc(h.p.slice(0,650))}${h.p.length>650?'…':''}</p><a class="excerpt-link" href="#read/${h.c.id}/${h.i}">${esc(h.c.title)}<span>进入卷轴 ↗</span></a></blockquote>`).join('')||'<p>暂未收录该群体的独立条目。</p>'}<div class="paths">${parisGroups.map((x,j)=>`<a href="#group/${j}">${x.name} ↗</a>`).join('')}</div></section>`}
function figuresPage(){return `<section class="section"><h1>具名人物索引</h1><a href="#characters" class="back-link">← 巴黎人物专题</a><div class="figure-grid">${entities.slice(5).map((e,i)=>`<a href="#entity/${i+5}">${image(e)}<h2>${e[0]}</h2><p>${e[1]}</p><span>人物档案 ↗</span></a>`).join('')}</div></section>`}
const previousNightRender=render;
render=function(){let [route,id]=decodeURI(location.hash.slice(1)).split('/');let html=route==='memory'||route==='places'?memoryPage():route==='characters'||route==='people'?charactersPage():route==='group'?groupPage(+id):route==='figures'?figuresPage():null;if(html!==null){document.querySelector('#app').innerHTML=html;window.scrollTo(0,0)}else previousNightRender();let nav=document.querySelector('nav');if(nav)nav.innerHTML='<a href="#library" class="nav-library">卷轴书库 ↗</a><a href="#memory">巴黎记忆</a><a href="#characters">巴黎人物</a><a href="#notebook">札记</a>';document.querySelectorAll('.art-plate figcaption').forEach(cap=>{cap.setAttribute('title',cap.textContent);});};
removeEventListener('hashchange',previousNightRender);addEventListener('hashchange',render);render();
